import { useEffect, useState } from "react";
import {
  Box,
  Button,
  Dialog,
  DialogContent,
  DialogTitle,
  Grid,
  Typography,
} from "@mui/material";
import axios from "axios";
import Dropzone from "./Dropzone";

const ImageUpload = () => {
  const [sliderImages, setSliderImages] = useState([]);
  const [bigPhotoImages, setBigPhotoImages] = useState([]);
  const [allPhotos, setAllPhotos] = useState([]);
  const [getAllPhotos, setGetAllPhotos] = useState([]);
  const [getBigPhoto, setGetBigPhoto] = useState([]);
  const [getSlider, setGetSlider] = useState([]);
  const [openGallery, setOpenGallery] = useState(false);

  const handleDrop = (category, files) => {
    if (category === "slider") setSliderImages((prev) => [...prev, ...files]);
    else if (category === "bigphoto") setBigPhotoImages((prev) => [...prev, ...files]);
    else if (category === "allphoto") setAllPhotos((prev) => [...prev, ...files]);
  };

  const handleUpload = async () => {
    const formData = new FormData();

    sliderImages.forEach((file) => formData.append("slider", file));
    bigPhotoImages.forEach((file) => formData.append("bigphoto", file));
    allPhotos.forEach((file) => formData.append("allphoto", file));

    try {
      const response = await axios.post("http://localhost:5000/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      console.log("Upload success:", response.data);
    } catch (error) {
      console.error("Error uploading images:", error);
    }
  };

  useEffect(() => {
    const fetchImages = async () => {
      try {
        const response = await axios.get("http://localhost:5000/images");
        setGetAllPhotos(response.data?.[0].allphoto || []);
        setGetBigPhoto(response.data?.[0].bigphoto || []);
        setGetSlider(response.data?.[0].slider || []);
      } catch (error) {
        console.error("Error fetching images:", error);
      }
    };
    fetchImages();
  }, []);

  return (
    <Box sx={{ maxWidth: 800, mx: "auto", p: 3 }}>
      <Typography variant="h5" sx={{ mb: 2, fontWeight: "bold", textAlign: "center" }}>
        Upload Images
      </Typography>

      <Grid container spacing={3}>
        <Grid item xs={12} md={4}>
          <Dropzone category="slider" onDrop={handleDrop} />
        </Grid>
        <Grid item xs={12} md={4}>
          <Dropzone category="bigphoto" onDrop={handleDrop} />
        </Grid>
        <Grid item xs={12} md={4}>
          <Dropzone category="allphoto" onDrop={handleDrop} />
        </Grid>
      </Grid>

      <Box sx={{ display: "flex", justifyContent: "center", mt: 3 }}>
        <Button variant="contained" color="primary" onClick={handleUpload} sx={{ mr: 2 }}>
          Upload
        </Button>
        <Button variant="outlined" color="secondary" onClick={() => setOpenGallery(true)}>
          Open Gallery
        </Button>
      </Box>

      {/* Gallery Popup */}
      <Dialog open={openGallery} onClose={() => setOpenGallery(false)} fullWidth maxWidth="md">
        <DialogTitle sx={{ fontWeight: "bold" }}>Photo Gallery</DialogTitle>
        <DialogContent>
          {[
            { title: "Slider Images", images: getSlider },
            { title: "Big Photos", images: getBigPhoto },
            { title: "All Photos", images: getAllPhotos },
          ].map(({ title, images }) => (
            <Box key={title} sx={{ mb: 2 }}>
              <Typography variant="h6" sx={{ fontWeight: "bold", mb: 1 }}>
                {title}
              </Typography>
              <Grid container spacing={2}>
                {images.map((img, index) => (
                  <Grid item xs={4} key={index}>
                    <img src={img.url} alt={title} style={{ width: "100%", height: "100px", objectFit: "cover", borderRadius: "8px" }} />
                  </Grid>
                ))}
              </Grid>
            </Box>
          ))}
        </DialogContent>
      </Dialog>
    </Box>
  );
};

export default ImageUpload;
